ST.xhtml:p:
(*防甩轴1*)
RelRtring1(CLK :=g_bAnRejection1RelEnable OR g_biAnRejection1RelEnable OR bAnRejection1RelEnable);
IF RelRtring1.Q THEN
  nRelState1 :=1;
  g_bAnRejection1RelDone := FALSE;
  g_boAnRejection1RelDone := FALSE;
  bAnRejection1RelDone := FALSE;
  IF g_biAnRejection1RelEnable THEN
    dARTargetPos1 := AntiRejection1.NCTOPLC.ActPos + g_fiARRelDis1;
    dARTargetVel1 := g_fiARRelVel1;
  ELSIF g_bAnRejection1RelEnable THEN
    dARTargetPos1 := AntiRejection1.NCTOPLC.ActPos + g_fARRelDis1;
    dARTargetVel1 := g_fARRelVel1;
    g_bAnRejection1RelEnable := FALSE;
  ELSE
      dARTargetPos1 := AntiRejection1.NCTOPLC.ActPos + dARRelDis1;
      IF g_bFastInch=0 THEN
        dARTargetVel1 := dAntiRejection1SlowVel;
      ELSE
        dARTargetVel1 := dAntiRejection1FastVel;
      END_IF;
      bAnRejection1RelEnable := FALSE; 
  END_IF;
  IF dARTargetVel1 = 0.0 THEN
    dARTargetVel1 := dAntiRejection1RelVelocity;
  END_IF;
END_IF;
IF NOT (g_bAnRejection1RelEnable OR g_biAnRejection1RelEnable OR bAnRejection1RelEnable) THEN
  g_bAnRejection1RelDone := FALSE;
  g_boAnRejection1RelDone := FALSE;
  bAnRejection1RelDone := FALSE;
END_IF;

CASE nRelState1 OF
  0:
  nRelState1 := 0;
  1:
  g_AntiRejection1Rel.Execute := TRUE;
  g_AntiRejection1Rel.Velocity := dARTargetVel1;
  g_AntiRejection1Rel.Distance := dARTargetPos1 - AntiRejection1.NCTOPLC.ACTPOS;
  IF g_AntiRejection1Rel.Done THEN
    g_AntiRejection1Rel.Execute := FALSE;
    bAnRejection1RelDone := TRUE;
    g_bAnRejection1RelDone :=TRUE;
    g_boAnRejection1RelDone := TRUE;
    nRelState1 := 0;
  END_IF;
  IF g_bPlcPauseBuffer THEN
    nRelState1 := 20;
  END_IF;
  IF g_AntiRejection1Rel.CommandAborted OR g_AntiRejection1Rel.Error THEN
    g_AntiRejection1Rel.Execute := FALSE;
    nRelState1 := 0;
  END_IF;
  20:
  g_AntiRejection1Rel.Execute := FALSE;
  g_AntiRejection1Stop.Execute := TRUE;
  IF g_AntiRejection1Stop.Done AND g_bPlcStartBuffer THEN
    g_AntiRejection1Stop.Execute := FALSE;
    nRelState1 := 1;
  END_IF;
  IF g_AntiRejection1Stop.CommandAborted OR g_AntiRejection1Stop.Error THEN 
    g_AntiRejection1Stop.Execute := FALSE;
    nRelState1 := 0;
  END_IF;
END_CASE;
IF g_bPlcResetBuffer THEN
  nRelState1 := 0;
  g_AntiRejection1Rel.Execute := FALSE;
  g_AntiRejection1Stop.Execute := FALSE;
END_IF;
